use crate::decision::Decision;
use crate::error::Error;
use crate::error::Result;
use crate::policy::MatchOptions;
use crate::policy::Policy;
use codex\_utils\_absolute\_path::AbsolutePathBuf;
use serde::Deserialize;
use serde::Serialize;
use shlex::try\_join;
use std::any::Any;
use std::fmt::Debug;
use std::sync::Arc;

/// Matches a single command token, either a fixed string or one of several allowed alternatives.
#\[derive(Clone, Debug, Eq, PartialEq)\]
pub enum PatternToken {
 Single(String),
 Alts(Vec),
}

impl PatternToken {
 fn matches(&self, token: &str) -> bool {
 match self {
 Self::Single(expected) => expected == token,
 Self::Alts(alternatives) => alternatives.iter().any(\|alt\| alt == token),
 }
 }

 pub fn alternatives(&self) -> &\[String\] {
 match self {
 Self::Single(expected) => std::slice::from\_ref(expected),
 Self::Alts(alternatives) => alternatives,
 }
 }
}

/// Prefix matcher for commands with support for alternative match tokens.
/// First token is fixed since we key by the first token in policy.
#\[derive(Clone, Debug, Eq, PartialEq)\]
pub struct PrefixPattern {
 pub first: Arc,
 pub rest: Arc<\[PatternToken\]>,
}

impl PrefixPattern {
 pub fn matches\_prefix(&self, cmd: &\[String\]) -> Option\> {
 let pattern\_length = self.rest.len() + 1;
 if cmd.len() < pattern\_length \|\| cmd\[0\] != self.first.as\_ref() {
 return None;
 }

 for (pattern\_token, cmd\_token) in self.rest.iter().zip(&cmd\[1..pattern\_length\]) {
 if !pattern\_token.matches(cmd\_token) {
 return None;
 }
 }

 Some(cmd\[..pattern\_length\].to\_vec())
 }
}

#\[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)\]
#\[serde(rename\_all = "camelCase")\]
pub enum RuleMatch {
 PrefixRuleMatch {
 #\[serde(rename = "matchedPrefix")\]
 matched\_prefix: Vec,
 decision: Decision,
 #\[serde(rename = "resolvedProgram", skip\_serializing\_if = "Option::is\_none")\]
 resolved\_program: Option,
 /// Optional rationale for why this rule exists.
 ///
 /// This can be supplied for any decision and may be surfaced in different contexts
 /// (e.g., prompt reasons or rejection messages).
 #\[serde(skip\_serializing\_if = "Option::is\_none")\]
 justification: Option,
 },
 HeuristicsRuleMatch {
 command: Vec,
 decision: Decision,
 },
}

impl RuleMatch {
 pub fn decision(&self) -> Decision {
 match self {
 Self::PrefixRuleMatch { decision, .. } => \*decision,
 Self::HeuristicsRuleMatch { decision, .. } => \*decision,
 }
 }

 pub fn with\_resolved\_program(self, resolved\_program: &AbsolutePathBuf) -> Self {
 match self {
 Self::PrefixRuleMatch {
 matched\_prefix,
 decision,
 justification,
 ..
 } =\> Self::PrefixRuleMatch {
 matched\_prefix,
 decision,
 resolved\_program: Some(resolved\_program.clone()),
 justification,
 },
 other => other,
 }
 }
}

#\[derive(Clone, Debug, Eq, PartialEq)\]
pub struct PrefixRule {
 pub pattern: PrefixPattern,
 pub decision: Decision,
 pub justification: Option,
}

#\[derive(Clone, Copy, Debug, Eq, PartialEq)\]
pub enum NetworkRuleProtocol {
 Http,
 Https,
 Socks5Tcp,
 Socks5Udp,
}

impl NetworkRuleProtocol {
 pub fn parse(raw: &str) -> Result {
 match raw {
 "http" => Ok(Self::Http),
 "https" \| "https\_connect" \| "http-connect" => Ok(Self::Https),
 "socks5\_tcp" => Ok(Self::Socks5Tcp),
 "socks5\_udp" => Ok(Self::Socks5Udp),
 other => Err(Error::InvalidRule(format!(
 "network\_rule protocol must be one of http, https, socks5\_tcp, socks5\_udp (got {other})"
 ))),
 }
 }

 pub fn as\_policy\_string(self) -> &'static str {
 match self {
 Self::Http => "http",
 Self::Https => "https",
 Self::Socks5Tcp => "socks5\_tcp",
 Self::Socks5Udp => "socks5\_udp",
 }
 }
}

#\[derive(Clone, Debug, Eq, PartialEq)\]
pub struct NetworkRule {
 pub host: String,
 pub protocol: NetworkRuleProtocol,
 pub decision: Decision,
 pub justification: Option,
}

pub(crate) fn normalize\_network\_rule\_host(raw: &str) -> Result {
 let mut host = raw.trim();
 if host.is\_empty() {
 return Err(Error::InvalidRule(
 "network\_rule host cannot be empty".to\_string(),
 ));
 }
 if host.contains("://") \|\| host.contains('/') \|\| host.contains('?') \|\| host.contains('#') {
 return Err(Error::InvalidRule(
 "network\_rule host must be a hostname or IP literal (without scheme or path)"
 .to\_string(),
 ));
 }

 if let Some(stripped) = host.strip\_prefix('\[') {
 let Some((inside, rest)) = stripped.split\_once('\]') else {
 return Err(Error::InvalidRule(
 "network\_rule host has an invalid bracketed IPv6 literal".to\_string(),
 ));
 };
 let port\_ok = rest
 .strip\_prefix(':')
 .is\_some\_and(\|port\| !port.is\_empty() && port.chars().all(\|c\| c.is\_ascii\_digit()));
 if !rest.is\_empty() && !port\_ok {
 return Err(Error::InvalidRule(format!(
 "network\_rule host contains an unsupported suffix: {raw}"
 )));
 }
 host = inside;
 } else if host.matches(':').count() == 1
 && let Some((candidate, port)) = host.rsplit\_once(':')
 && !candidate.is\_empty()
 && !port.is\_empty()
 && port.chars().all(\|c\| c.is\_ascii\_digit())
 {
 host = candidate;
 }

 let normalized = host.trim\_end\_matches('.').trim().to\_ascii\_lowercase();
 if normalized.is\_empty() {
 return Err(Error::InvalidRule(
 "network\_rule host cannot be empty".to\_string(),
 ));
 }
 if normalized.contains('\*') {
 return Err(Error::InvalidRule(
 "network\_rule host must be a specific host; wildcards are not allowed".to\_string(),
 ));
 }
 if normalized.chars().any(char::is\_whitespace) {
 return Err(Error::InvalidRule(
 "network\_rule host cannot contain whitespace".to\_string(),
 ));
 }

 Ok(normalized)
}

pub trait Rule: Any + Debug + Send + Sync {
 fn program(&self) -> &str;

 fn matches(&self, cmd: &\[String\]) -> Option;

 fn as\_any(&self) -> &dyn Any;
}

pub type RuleRef = Arc;

impl Rule for PrefixRule {
 fn program(&self) -> &str {
 self.pattern.first.as\_ref()
 }

 fn matches(&self, cmd: &\[String\]) -> Option {
 self.pattern
 .matches\_prefix(cmd)
 .map(\|matched\_prefix\| RuleMatch::PrefixRuleMatch {
 matched\_prefix,
 decision: self.decision,
 resolved\_program: None,
 justification: self.justification.clone(),
 })
 }

 fn as\_any(&self) -> &dyn Any {
 self
 }
}

/// Count how many rules match each provided example and error if any example is unmatched.
pub(crate) fn validate\_match\_examples(
 policy: &Policy,
 rules: &\[RuleRef\],
 matches: &\[Vec\],
) -\> Result<()> {
 let mut unmatched\_examples = Vec::new();
 let options = MatchOptions {
 resolve\_host\_executables: true,
 };

 for example in matches {
 if !policy
 .matches\_for\_command\_with\_options(example, /\*heuristics\_fallback\*/ None, &options)
 .is\_empty()
 {
 continue;
 }

 unmatched\_examples.push(
 try\_join(example.iter().map(String::as\_str))
 .unwrap\_or\_else(\|\_\| "unable to render example".to\_string()),
 );
 }

 if unmatched\_examples.is\_empty() {
 Ok(())
 } else {
 Err(Error::ExampleDidNotMatch {
 rules: rules.iter().map(\|rule\| format!("{rule:?}")).collect(),
 examples: unmatched\_examples,
 location: None,
 })
 }
}

/// Ensure that no rule matches any provided negative example.
pub(crate) fn validate\_not\_match\_examples(
 policy: &Policy,
 \_rules: &\[RuleRef\],
 not\_matches: &\[Vec\],
) -\> Result<()> {
 let options = MatchOptions {
 resolve\_host\_executables: true,
 };

 for example in not\_matches {
 if let Some(rule) = policy
 .matches\_for\_command\_with\_options(example, /\*heuristics\_fallback\*/ None, &options)
 .first()
 {
 return Err(Error::ExampleDidMatch {
 rule: format!("{rule:?}"),
 example: try\_join(example.iter().map(String::as\_str))
 .unwrap\_or\_else(\|\_\| "unable to render example".to\_string()),
 location: None,
 });
 }
 }

 Ok(())
}

